const xml = $input.first().json.body || '';
const results = [];

// Reddit RSS uses Atom format with <entry> elements
const entryPattern = /<entry>([\s\S]*?)<\/entry>/gi;
let entryMatch;

while ((entryMatch = entryPattern.exec(xml)) !== null) {
  const entryXml = entryMatch[1];

  const titleMatch = entryXml.match(/<title[^>]*>([^<]*)<\/title>/);
  const linkMatch = entryXml.match(/<link[^>]*href="([^"]+)"/);
  const updatedMatch = entryXml.match(/<updated>([^<]*)<\/updated>/);
  const authorMatch = entryXml.match(/<name>([^<]*)<\/name>/);

  const title = titleMatch ? titleMatch[1].trim() : 'Untitled';
  const link = linkMatch ? linkMatch[1].trim() : '';
  const updated = updatedMatch ? updatedMatch[1].trim() : '';
  const author = authorMatch ? authorMatch[1].trim() : '';

  if (title && link) {
    results.push({
      json: {
        title,
        link,
        published_at: updated,
        author,
        source: 'reddit_uniuk',
        subreddit: 'UniUK'
      }
    });
  }
}

return results.length > 0 ? results : [{ json: { title: 'No posts found', link: '', source: 'reddit_uniuk', subreddit: 'UniUK' } }];

